response:
1.  Create a new HTML file named “search.html” in the same directory as the index.html file.  Add this code to the head of the document:

<script>
const search = document.getElementById("search");
const resultsContainer = document.getElementById("results");

function loadResults() {
  const query = search.value;
  if(query) {
    let url = "https://elastic-search-service.herokuapp.com/api/autocomplete/" + query;
    fetch(url).then(response => response.json()).then(data => {
      data.results.forEach(result => {
        let item = document.createElement("li");
        item.innerHTML = result.text;
        resultsContainer.appendChild(item);
      });
    }).catch(() => console.log("No results found"));
  } else {
    resultsContainer.innerHTML = "";
  }
}

search.oninput = function() {
  loadResults();
};
</script>

