import React from 'react';

function MyComponent() {
  let currentValue = 0;
  let incrementButton = <button onClick={() => currentValue++}>Increment</button>;
  let decrementButton = <button onClick={() => currentValue--}>Decrement</button>;

  return (
    <div>
      <h1>Current value is {currentValue}</h1>
      <input type="number" value={currentValue} onChange={(event) => currentValue = event.target.value} />
      <button onClick={() => currentValue++;} style={{marginLeft: "5px", marginRight: "5px"}}>+</button>
      <button onClick={() => currentValue--}>-</button>
    </div>
